def _children(stage):
    return sorted(name for name, deps in DEPENDENCIES.items() if stage in deps)


def descendants(stage):
    out, queue = [], [stage]
    while queue:
        parent = queue.pop(0)
        for child in _children(parent):
            if child not in out:
                out.append(child); queue.append(child)
    return out


